// DeleteUniqueIndexCache 删除索引存在的缓存
func (s *SysAdminDeptRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.SysAdminDept) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, s.cache.Key(CacheSysAdminDeptByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[s.cache.Key(CacheSysAdminDeptByAdminIDPrefix, item.AdminID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSysAdminDeptByDeptIDPrefix, item.DeptID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := s.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
